import React, { useState, useEffect } from 'react';
import { Card, Button, Alert, api } from '../App';

const UploadBox = ({ title, desc, color, onUpload, loading, result }) => {
  const [file, setFile] = useState(null);
  const [drag, setDrag] = useState(false);

  const handleFile = f => {
    if (!f) return;
    const ext = f.name.split('.').pop().toLowerCase();
    if (!['xlsx','xls','csv'].includes(ext)) { alert('Only .xlsx, .xls, .csv allowed'); return; }
    setFile(f);
  };

  return (
    <Card style={{ flex:1, border:`2px solid ${drag ? color : '#e2e8f0'}`, transition:'border 0.2s' }}>
      <div style={{ borderLeft:`4px solid ${color}`, paddingLeft:12, marginBottom:14 }}>
        <h3 style={{ fontSize:15, color:'#1a2533' }}>{title}</h3>
        <p style={{ fontSize:12, color:'#888', marginTop:2 }}>{desc}</p>
      </div>
      <div
        onDragOver={e => { e.preventDefault(); setDrag(true); }}
        onDragLeave={() => setDrag(false)}
        onDrop={e => { e.preventDefault(); setDrag(false); handleFile(e.dataTransfer.files[0]); }}
        style={{ border:'2px dashed #cbd5e0', borderRadius:8, padding:'24px 16px', textAlign:'center', cursor:'pointer', background:drag?'#f0f8ff':'#fafbfc', marginBottom:12 }}
        onClick={() => document.getElementById(`fu-${title.replace(/\s/g,'')}`).click()}
      >
        <input id={`fu-${title.replace(/\s/g,'')}`} type="file" accept=".xlsx,.xls,.csv" style={{ display:'none' }} onChange={e => handleFile(e.target.files[0])} />
        {file ? (
          <><div style={{ fontSize:26 }}>📄</div><div style={{ fontSize:13, fontWeight:600, color:'#333', marginTop:4 }}>{file.name}</div><div style={{ fontSize:11, color:'#888' }}>{(file.size/1024).toFixed(1)} KB</div></>
        ) : (
          <><div style={{ fontSize:30, marginBottom:4 }}>📥</div><div style={{ fontSize:13, color:'#666' }}>Drag & drop or <span style={{ color, fontWeight:600 }}>browse</span></div><div style={{ fontSize:11, color:'#aaa', marginTop:2 }}>.xlsx · .xls · .csv</div></>
        )}
      </div>

      {result && (
        <div style={{ background: result.error ? '#fee2e2' : '#f0fdf4', border:`1px solid ${result.error?'#fecaca':'#bbf7d0'}`, borderRadius:8, padding:'10px 14px', marginBottom:10, fontSize:13, color: result.error?'#991b1b':'#166534' }}>
          {result.error ? `❌ ${result.error}` : `✅ Imported ${result.imported} rows · Skipped ${result.skipped}${result.sale_no ? ` · Sale #${result.sale_no}` : ''}`}
        </div>
      )}
      {result?.errors?.length > 0 && (
        <div style={{ fontSize:11, color:'#c0392b', background:'#fee2e2', padding:8, borderRadius:4, marginBottom:8 }}>
          {result.errors.slice(0,3).map((e,i) => <div key={i}>{e}</div>)}
        </div>
      )}

      <div style={{ display:'flex', gap:8 }}>
        <Button onClick={() => { if (file) onUpload(file); }} disabled={!file || loading} variant="primary" style={{ flex:1, background:color }}>
          {loading ? 'Uploading…' : `⬆ Upload ${title}`}
        </Button>
        {file && <Button onClick={() => setFile(null)} variant="outline" size="sm">Clear</Button>}
      </div>
    </Card>
  );
};

export default function ImportPage() {
  const [catResult,   setCatResult]   = useState(null);
  const [soldResult,  setSoldResult]  = useState(null);
  const [catLoading,  setCatLoading]  = useState(false);
  const [soldLoading, setSoldLoading] = useState(false);
  const [merged,      setMerged]      = useState([]);
  const [saleNos,     setSaleNos]     = useState([]);
  const [selSale,     setSelSale]     = useState('');
  const [gradeFilter, setGradeFilter] = useState('');
  const [gardenFilter,setGardenFilter]= useState('');

  const loadSaleNos = () => api.get('/import/sale-numbers').then(r => { setSaleNos(r.data); if(r.data[0]) setSelSale(r.data[0].sale_no); }).catch(()=>{});

  useEffect(() => { loadSaleNos(); }, []);

  useEffect(() => {
    if (!selSale) return;
    api.get(`/catalogue/merged?sale_no=${selSale}`).then(r => setMerged(r.data)).catch(()=>{});
  }, [selSale]);

  const uploadCatalogue = async (file) => {
    setCatLoading(true);
    const fd = new FormData(); fd.append('file', file);
    try {
      const r = await api.post('/import/catalogue', fd);
      setCatResult(r.data);
      loadSaleNos();
      if (r.data.sale_no) { setSelSale(r.data.sale_no); }
    } catch (e) { setCatResult({ error: e.response?.data?.error || e.message }); }
    finally { setCatLoading(false); }
  };

  const uploadSoldList = async (file) => {
    setSoldLoading(true);
    const fd = new FormData(); fd.append('file', file);
    try {
      const r = await api.post('/import/sold-list', fd);
      setSoldResult(r.data);
      if (selSale) api.get(`/catalogue/merged?sale_no=${selSale}`).then(r2 => setMerged(r2.data)).catch(()=>{});
    } catch (e) { setSoldResult({ error: e.response?.data?.error || e.message }); }
    finally { setSoldLoading(false); }
  };

  const grades   = [...new Set(merged.map(r => r.grade).filter(Boolean))].sort();
  const gardens  = [...new Set(merged.map(r => r.garden).filter(Boolean))].sort();
  const filtered = merged.filter(r =>
    (!gradeFilter  || r.grade  === gradeFilter) &&
    (!gardenFilter || r.garden === gardenFilter)
  );

  const fmt = v => v !== null && v !== undefined ? Number(v).toFixed(2) : '—';

  return (
    <div>
      <h2 style={{ marginBottom:4, color:'#1a3c5e' }}>📥 Import Excel Files</h2>
      <p style={{ color:'#888', fontSize:13, marginBottom:20 }}>Upload Catalogue (every Thursday) and Sold List from auction software. Duplicates handled automatically.</p>

      <div style={{ display:'flex', gap:16, marginBottom:20, flexWrap:'wrap' }}>
        <UploadBox title="Catalogue"  desc="Weekly catalogue — columns: Sale No, LotNo, Auctioneer, Origin, Mark, Grade, No of Packages, Net Weight, LastSoldPrice, GPDate, InvoiceNo"
          color="#1a3c5e" onUpload={uploadCatalogue} loading={catLoading} result={catResult} />
        <UploadBox title="Sold List"  desc="Current week sold list — columns: Mark, Grade, DealPrice (and garden names in rows)"
          color="#1a7a4a" onUpload={uploadSoldList} loading={soldLoading} result={soldResult} />
      </div>

      {/* MERGED TABLE */}
      <Card>
        <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:14, flexWrap:'wrap', gap:10 }}>
          <h3 style={{ fontSize:15 }}>📋 Imported Data — Catalogue + Sold List (Merged)</h3>
          <div style={{ display:'flex', gap:10, flexWrap:'wrap', alignItems:'center' }}>
            {saleNos.length > 0 && (
              <select value={selSale} onChange={e => setSelSale(e.target.value)}
                style={{ padding:'6px 10px', border:'1.5px solid #cbd5e0', borderRadius:6, fontSize:13 }}>
                {saleNos.map(s => <option key={s.sale_no} value={s.sale_no}>Sale {s.sale_no}</option>)}
              </select>
            )}
            <select value={gradeFilter} onChange={e => setGradeFilter(e.target.value)}
              style={{ padding:'6px 10px', border:'1.5px solid #cbd5e0', borderRadius:6, fontSize:13 }}>
              <option value="">All Grades</option>
              {grades.map(g => <option key={g} value={g}>{g}</option>)}
            </select>
            <select value={gardenFilter} onChange={e => setGardenFilter(e.target.value)}
              style={{ padding:'6px 10px', border:'1.5px solid #cbd5e0', borderRadius:6, fontSize:13 }}>
              <option value="">All Gardens</option>
              {gardens.map(g => <option key={g} value={g}>{g}</option>)}
            </select>
            {(gradeFilter || gardenFilter) && (
              <Button size="sm" variant="outline" onClick={() => { setGradeFilter(''); setGardenFilter(''); }}>Clear</Button>
            )}
          </div>
        </div>

        {filtered.length === 0 ? (
          <div style={{ padding:30, textAlign:'center', color:'#aaa' }}>
            {selSale ? 'No data found. Upload Catalogue first.' : 'Select a sale number above.'}
          </div>
        ) : (
          <>
            <div style={{ fontSize:12, color:'#888', marginBottom:8 }}>Showing {filtered.length} of {merged.length} lots</div>
            <div style={{ overflowX:'auto' }}>
              <table style={{ width:'100%', borderCollapse:'collapse', fontSize:12 }}>
                <thead>
                  <tr style={{ background:'#f0f4f8' }}>
                    {['Sale No','Origin (Garden)','Mark','Grade','Bags','Net Wt','Min Price ₹','Max Price ₹','Last Sale Price ₹','Deal Price ₹','Broker'].map(h => (
                      <th key={h} style={{ padding:'8px 10px', textAlign:'left', fontWeight:700, color:'#444', borderBottom:'2px solid #e2e8f0', whiteSpace:'nowrap' }}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {filtered.slice(0,200).map((row, i) => (
                    <tr key={i} style={{ borderBottom:'1px solid #f0f4f8', background:i%2===0?'#fff':'#fafbfc' }}>
                      <td style={{ padding:'6px 10px', fontWeight:600 }}>{row.sale_no}</td>
                      <td style={{ padding:'6px 10px', fontWeight:600, color:'#1a3c5e' }}>{row.garden}</td>
                      <td style={{ padding:'6px 10px' }}>{row.mark}</td>
                      <td style={{ padding:'6px 10px' }}>
                        <span style={{ background:'#dbeafe', color:'#1e40af', padding:'2px 8px', borderRadius:99, fontSize:11, fontWeight:700 }}>{row.grade}</span>
                      </td>
                      <td style={{ padding:'6px 10px' }}>{row.bags || '—'}</td>
                      <td style={{ padding:'6px 10px' }}>{row.net_wt || '—'}</td>
                      <td style={{ padding:'6px 10px', color:'#1a7a4a', fontWeight:600 }}>{row.min_last_price ? `₹${fmt(row.min_last_price)}` : '—'}</td>
                      <td style={{ padding:'6px 10px', color:'#c0392b', fontWeight:600 }}>{row.max_last_price ? `₹${fmt(row.max_last_price)}` : '—'}</td>
                      <td style={{ padding:'6px 10px', color:'#555' }}>{row.last_sale_price ? `₹${fmt(row.last_sale_price)}` : '—'}</td>
                      <td style={{ padding:'6px 10px', fontWeight:700, color: row.current_sold_price ? '#0f766e' : '#aaa' }}>
                        {row.current_sold_price ? `₹${fmt(row.current_sold_price)}` : <span style={{ color:'#f59e0b', fontSize:11 }}>not sold</span>}
                      </td>
                      <td style={{ padding:'6px 10px', color:'#888', fontSize:11 }}>{row.broker || '—'}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
              {filtered.length > 200 && <div style={{ padding:10, textAlign:'center', color:'#888', fontSize:12 }}>Showing first 200 of {filtered.length} rows. Use filters to narrow down.</div>}
            </div>
          </>
        )}
      </Card>
    </div>
  );
}
